<template>
  <section class="space-y-4">
    <div class="flex flex-wrap items-center justify-between gap-2"><div><h3 class="text-sm font-semibold">面试流程</h3><p class="mt-1 text-xs text-muted-foreground">各轮面试独立记录结论；流程结束时再填写最终录用结论。时间均为北京时间。</p></div><div class="flex gap-2"><Button variant="outline" size="sm" :disabled="busy || loading" @click="load">刷新</Button><Button size="sm" :disabled="busy || loading || !canCreate || hasActive" @click="openCreate"><Plus />安排面试</Button></div></div>
    <Callout v-if="error" tone="destructive" title="面试流程加载失败">{{ error }}</Callout><p v-else-if="loading" class="text-sm text-muted-foreground">正在加载面试流程…</p><EmptyState v-else-if="!processes.length" title="还没有面试流程" :description="canCreate ? '安排面试后，可逐轮填写时间、结论与反馈。' : '先完成简历识别并核对候选人姓名，再安排面试。'"><Button v-if="canCreate" size="sm" @click="openCreate"><Plus />安排面试</Button></EmptyState>
    <section v-for="process in processes" :key="process.id" class="overflow-hidden rounded-lg border">
      <header class="flex flex-wrap items-center justify-between gap-3 bg-muted/40 p-4"><div><div class="flex flex-wrap items-center gap-2"><h4 class="text-sm font-semibold">{{ process.position }}</h4><Badge :variant="process.status === 'active' ? 'info' : process.result === 'passed' ? 'success' : process.result === 'rejected' ? 'destructive' : 'secondary'">{{ process.status === 'active' ? '进行中' : process.status === 'cancelled' ? '已取消' : process.result === 'passed' ? '已结束 · 通过' : '已结束 · 未通过' }}</Badge></div><p class="mt-1 text-xs text-muted-foreground">{{ process.createdBy }} · {{ formatPortalDateTime(process.createdAt) }}</p></div><div v-if="process.status === 'active'" class="flex gap-2"><Button variant="outline" size="sm" :disabled="busy" @click="openFinish(process, false)">结束流程</Button><DropdownMenu><template #trigger><Button variant="ghost" size="icon-sm" :disabled="busy" aria-label="面试流程更多操作"><MoreHorizontal /></Button></template><DropdownMenuItem destructive :disabled="busy" @select="openFinish(process, true)">取消面试流程</DropdownMenuItem></DropdownMenu></div></header>
      <div class="overflow-x-auto"><table class="data-table min-w-[700px]"><thead><tr><th>轮次</th><th>面试官 / 时间 / 地点</th><th>状态 / 结论</th><th>面试反馈</th><th class="sticky-col text-right">操作</th></tr></thead><tbody><tr v-for="round in process.rounds" :key="round.id"><td class="font-medium">{{ round.sequence }}. {{ round.name }}</td><td class="text-xs"><p>{{ round.interviewer || '面试官待定' }}</p><p class="mt-1 text-muted-foreground">{{ displayTime(round.scheduledAt) || '时间待定' }}</p><p v-if="round.location" class="mt-1 text-muted-foreground">{{ round.location }}</p></td><td><Badge :variant="round.status === 'pending' ? 'secondary' : round.result === 'passed' ? 'success' : round.result === 'rejected' ? 'destructive' : 'secondary'">{{ round.status === 'pending' ? '待面试' : round.status === 'cancelled' ? '已取消' : round.result === 'passed' ? '已完成 · 通过' : '已完成 · 未通过' }}</Badge></td><td class="max-w-72 text-xs text-muted-foreground"><p class="whitespace-pre-wrap break-words">{{ round.feedback || '–' }}</p></td><td class="sticky-col text-right"><Button v-if="process.status === 'active'" variant="ghost" size="sm" :disabled="busy" @click="openRound(process, round)">编辑记录</Button><span v-else class="text-xs text-muted-foreground">已归档</span></td></tr></tbody></table></div>
      <div v-if="process.summary" class="border-t px-4 py-3 text-xs leading-6"><b class="font-medium">流程总结：</b><span class="whitespace-pre-wrap text-muted-foreground">{{ process.summary }}</span></div>
    </section>
    <Dialog :open="createOpen" title="安排候选人面试" size="lg" @update:open="!busy && (createOpen = $event)">
      <form id="resume-interview-create" class="space-y-4" @submit.prevent="create"><Callout v-if="formError" tone="destructive">{{ formError }}</Callout><div><label for="interview-position" class="field-label">面试岗位 *</label><Input id="interview-position" v-model="createForm.position" required maxlength="120" /></div><div class="flex items-center justify-between"><p class="text-sm font-medium">面试轮次</p><Button size="sm" variant="outline" :disabled="createForm.rounds.length >= 10" @click="addRound"><Plus />添加轮次</Button></div><div v-for="(round, i) in createForm.rounds" :key="i" class="space-y-3 rounded-lg border p-4"><div class="flex items-center justify-between"><span class="text-xs font-medium">第 {{ i + 1 }} 轮</span><Button size="sm" variant="ghost" :disabled="createForm.rounds.length <= 1" @click="createForm.rounds.splice(i, 1)">移除</Button></div><div class="grid gap-3 sm:grid-cols-2"><div><label :for="`interview-new-name-${i}`" class="field-label">轮次名称 *</label><Input :id="`interview-new-name-${i}`" v-model="round.name" required maxlength="100" /></div><div><label :for="`interview-new-owner-${i}`" class="field-label">面试官</label><Input :id="`interview-new-owner-${i}`" v-model="round.interviewer" maxlength="100" /></div><div><label :for="`interview-new-time-${i}`" class="field-label">面试时间（北京）</label><Input :id="`interview-new-time-${i}`" v-model="round.scheduledAt" type="datetime-local" /></div><div><label :for="`interview-new-location-${i}`" class="field-label">地点 / 会议链接</label><Input :id="`interview-new-location-${i}`" v-model="round.location" maxlength="500" /></div></div></div></form>
      <template #footer><Button variant="outline" :disabled="busy" @click="createOpen = false">取消</Button><Button type="submit" form="resume-interview-create" :loading="busy">创建面试流程</Button></template>
    </Dialog>
    <Dialog :open="!!editingRound" title="编辑面试轮次" size="lg" @update:open="!busy && !$event && (editingRound = null)">
      <form id="resume-interview-round" class="space-y-4" @submit.prevent="saveRound"><Callout v-if="formError" tone="destructive">{{ formError }}</Callout><div class="grid gap-3 sm:grid-cols-2"><div><label for="interview-round-name" class="field-label">轮次名称 *</label><Input id="interview-round-name" v-model="roundForm.name" required maxlength="100" /></div><div><label for="interview-round-owner" class="field-label">面试官</label><Input id="interview-round-owner" v-model="roundForm.interviewer" maxlength="100" /></div><div><label for="interview-round-time" class="field-label">面试时间（北京）</label><Input id="interview-round-time" v-model="roundForm.scheduledAt" type="datetime-local" /></div><div><label for="interview-round-location" class="field-label">地点 / 会议链接</label><Input id="interview-round-location" v-model="roundForm.location" maxlength="500" /></div><div><label for="interview-round-status" class="field-label">轮次状态</label><Select id="interview-round-status" v-model="roundForm.status" :options="[{ value: 'pending', label: '待面试' }, { value: 'completed', label: '已完成' }, { value: 'cancelled', label: '已取消' }]" /></div><div v-if="roundForm.status === 'completed'"><label for="interview-round-result" class="field-label">本轮结论 *</label><Select id="interview-round-result" v-model="roundForm.result" :options="[{ value: '', label: '请选择结论' }, { value: 'passed', label: '通过' }, { value: 'rejected', label: '未通过' }]" /></div></div><div><label for="interview-round-feedback" class="field-label">面试反馈{{ roundForm.status === 'completed' ? ' *' : '' }}</label><Textarea id="interview-round-feedback" v-model="roundForm.feedback" :required="roundForm.status === 'completed'" maxlength="5000" :rows="6" /></div></form>
      <template #footer><Button variant="outline" :disabled="busy" @click="editingRound = null">取消</Button><Button type="submit" form="resume-interview-round" :loading="busy">保存面试记录</Button></template>
    </Dialog>
    <Dialog :open="!!finishing" :title="finishing?.cancel ? '取消面试流程' : '结束面试流程'" @update:open="!busy && !$event && (finishing = null)">
      <form id="resume-interview-finish" class="space-y-4" @submit.prevent="finish"><Callout v-if="formError" tone="destructive">{{ formError }}</Callout><Callout>流程关闭后只读，尚未完成的轮次会取消。</Callout><div v-if="!finishing?.cancel"><label for="interview-final-result" class="field-label">流程最终结论 *</label><Select id="interview-final-result" v-model="finishForm.result" :options="[{ value: 'passed', label: '通过' }, { value: 'rejected', label: '未通过' }]" /></div><div><label for="interview-final-summary" class="field-label">{{ finishing?.cancel ? '取消原因' : '流程总结' }} *</label><Textarea id="interview-final-summary" v-model="finishForm.summary" required maxlength="5000" :rows="6" /></div></form><template #footer><Button variant="outline" :disabled="busy" @click="finishing = null">返回</Button><Button type="submit" form="resume-interview-finish" :loading="busy">确认{{ finishing?.cancel ? '取消' : '结束' }}</Button></template>
    </Dialog>
  </section>
</template>
<script setup lang="ts">
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { MoreHorizontal, Plus } from '@lucide/vue'
import { api } from '../../lib/api'
import { errText, toast } from '../../lib/toast'
import Badge from '../../ui/Badge.vue'
import Button from '../../ui/Button.vue'
import Callout from '../../ui/Callout.vue'
import Dialog from '../../ui/Dialog.vue'
import EmptyState from '../../ui/EmptyState.vue'
import DropdownMenu from '../../ui/DropdownMenu.vue'
import DropdownMenuItem from '../../ui/DropdownMenuItem.vue'
import { formatPortalDateTime } from '../../lib/portal-management-format'
import Input from '../../ui/Input.vue'
import Select from '../../ui/Select.vue'
import Textarea from '../../ui/Textarea.vue'
interface Round { id: number; sequence: number; name: string; interviewer?: string; scheduledAt?: string; location?: string; status: string; result?: string; feedback?: string }
interface Interview { id: number; position: string; status: string; result?: string; summary?: string; createdBy: string; createdAt: string; rounds: Round[] }
const props = defineProps<{ resumeId: number; canCreate: boolean; defaultPosition?: string }>()
const base = computed(() => `/admin-api/portal/resumes/${props.resumeId}/interviews`)
const processes = ref<Interview[]>([]), loading = ref(false), busy = ref(false), error = ref(''), formError = ref(''), createOpen = ref(false)
const hasActive = computed(() => processes.value.some(p => p.status === 'active'))
const blankRound = (name = '初面') => ({ name, interviewer: '', scheduledAt: '', location: '' })
const createForm = reactive({ position: '', rounds: [blankRound()] })
const editingRound = ref<{ processId: number; roundId: number } | null>(null), roundForm = reactive({ name: '', interviewer: '', scheduledAt: '', location: '', status: 'pending', result: '', feedback: '' })
const finishing = ref<{ processId: number; cancel: boolean } | null>(null), finishForm = reactive({ result: 'passed', summary: '' })
let seq = 0
function localTime(value?: string) { if (!value) return ''; const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(date).replace(' ', 'T') }
const displayTime = (value?: string) => localTime(value).replace('T', ' ')
const apiTime = (value: string) => value ? `${value}:00+08:00` : null
async function load() { const current = ++seq; loading.value = true; error.value = ''; try { const data = await api.get<Interview[]>(base.value); if (current === seq) processes.value = data } catch (e) { if (current === seq) error.value = errText(e) } finally { if (current === seq) loading.value = false } }
function openCreate() { createForm.position = props.defaultPosition ?? ''; createForm.rounds = [blankRound()]; formError.value = ''; createOpen.value = true }
function addRound() { createForm.rounds.push(blankRound(`第 ${createForm.rounds.length + 1} 轮面试`)) }
async function create() { if (busy.value) return; busy.value = true; formError.value = ''; try { await api.post(base.value, { position: createForm.position.trim(), rounds: createForm.rounds.map(r => ({ name: r.name.trim(), interviewer: r.interviewer.trim() || null, scheduledAt: apiTime(r.scheduledAt), location: r.location.trim() || null })) }); createOpen.value = false; toast('面试流程已安排'); await load() } catch (e) { formError.value = errText(e) } finally { busy.value = false } }
function openRound(process: Interview, round: Round) { editingRound.value = { processId: process.id, roundId: round.id }; Object.assign(roundForm, { name: round.name, interviewer: round.interviewer ?? '', scheduledAt: localTime(round.scheduledAt), location: round.location ?? '', status: round.status, result: round.result ?? '', feedback: round.feedback ?? '' }); formError.value = '' }
async function saveRound() { if (!editingRound.value || busy.value) return; if (roundForm.status === 'completed' && (!roundForm.result || !roundForm.feedback.trim())) { formError.value = '完成面试须填写本轮结论和反馈'; return } busy.value = true; formError.value = ''; try { await api.put(`${base.value}/${editingRound.value.processId}/rounds/${editingRound.value.roundId}`, { ...roundForm, scheduledAt: apiTime(roundForm.scheduledAt), result: roundForm.status === 'completed' ? roundForm.result : null }); editingRound.value = null; toast('面试记录已保存'); await load() } catch (e) { formError.value = errText(e) } finally { busy.value = false } }
function openFinish(process: Interview, cancel: boolean) { finishing.value = { processId: process.id, cancel }; Object.assign(finishForm, { result: 'passed', summary: '' }); formError.value = '' }
async function finish() { if (!finishing.value || busy.value) return; busy.value = true; formError.value = ''; try { await api.post(`${base.value}/${finishing.value.processId}/${finishing.value.cancel ? 'cancel' : 'finish'}`, { result: finishing.value.cancel ? undefined : finishForm.result, summary: finishForm.summary.trim() }); finishing.value = null; toast('面试流程已关闭'); await load() } catch (e) { formError.value = errText(e) } finally { busy.value = false } }
watch(() => props.resumeId, () => { processes.value = []; void load() }, { immediate: true })
onUnmounted(() => { seq++ })
</script>
